import numpy as np
from collections import Counter
def comps(A,val,bg):
    seen=np.zeros_like(A); out=[]
    for i in range(A.shape[0]):
        for j in range(A.shape[1]):
            if A[i,j]==val and not seen[i,j]:
                st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if 0<=y<A.shape[0] and 0<=x<A.shape[1] and A[y,x]==val and not seen[y,x]:
                        seen[y,x]=True; cells.append((y,x))
                        st+= [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                out.append(cells)
    return out
for k in ['Demo pair 1 input','Demo pair 2 input']:
